/**
 * app.test.js
 * Unit / integration tests for the /users endpoint in app.js.
 *
 * Test groups
 * ───────────
 * 1. Happy path          – successful requests return correct data
 * 2. Response schema     – payload shape matches the expected contract
 * 3. HTTP semantics      – correct status codes, headers, and methods
 * 4. Error handling      – simulate and verify server-side failure behaviour
 *
 * Dependencies (install before running):
 *   npm install --save-dev jest supertest
 *
 * Run:
 *   npm test                  (all tests)
 *   npm run test:coverage     (with coverage report)
 */

const request = require('supertest');
const express = require('express');

// ─── helpers ────────────────────────────────────────────────────────────────

/**
 * Re-import a fresh copy of app so each suite can monkey-patch routes without
 * polluting other test files.  Jest's module cache is cleared between files,
 * but within this file we sometimes need two different versions of the router
 * (nominal vs. error-throwing), so we build them with a small factory.
 */
function buildNominalApp() {
  const app = require('./app');
  return app;
}

/**
 * Builds a minimal Express app whose /users handler throws synchronously.
 * Used to verify that the error-handling tests are exercising a real failure
 * path rather than the happy-path code.
 */
function buildErrorApp() {
  const app = express();

  app.get('/users', (req, res, next) => {
    next(new Error('Database connection lost'));
  });

  // Express 4 error-handling middleware (4 parameters required)
  // eslint-disable-next-line no-unused-vars
  app.use((err, req, res, next) => {
    res
      .status(500)
      .json({ error: 'Internal Server Error', message: err.message });
  });

  return app;
}

/**
 * Validates that a single user object conforms to the expected schema.
 * Returns an array of human-readable violation strings (empty = valid).
 */
function validateUserSchema(user) {
  const violations = [];

  if (typeof user.id !== 'number') {
    violations.push(`"id" must be a number, got ${typeof user.id}`);
  }
  if (!Number.isInteger(user.id) || user.id <= 0) {
    violations.push(`"id" must be a positive integer, got ${user.id}`);
  }
  if (typeof user.name !== 'string' || user.name.trim() === '') {
    violations.push(`"name" must be a non-empty string, got "${user.name}"`);
  }
  if (typeof user.email !== 'string') {
    violations.push(`"email" must be a string, got ${typeof user.email}`);
  }
  // Basic RFC-5322-compatible e-mail surface check
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(user.email)) {
    violations.push(`"email" has invalid format: "${user.email}"`);
  }
  // Guard against unexpected extra properties that would widen the contract
  const allowedKeys = new Set(['id', 'name', 'email']);
  Object.keys(user).forEach((key) => {
    if (!allowedKeys.has(key)) {
      violations.push(`unexpected property "${key}" found on user object`);
    }
  });

  return violations;
}

// ─── 1. Happy-path tests ─────────────────────────────────────────────────────

describe('GET /users — happy path', () => {
  let app;

  beforeAll(() => {
    app = buildNominalApp();
  });

  it('responds with HTTP 200 OK', async () => {
    const res = await request(app).get('/users');
    expect(res.statusCode).toBe(200);
  });

  it('returns a non-empty array', async () => {
    const res = await request(app).get('/users');
    expect(Array.isArray(res.body)).toBe(true);
    expect(res.body.length).toBeGreaterThan(0);
  });

  it('contains the expected seed users (Alice and Bob)', async () => {
    const res = await request(app).get('/users');
    const names = res.body.map((u) => u.name);
    expect(names).toContain('Alice');
    expect(names).toContain('Bob');
  });

  it('returns exactly 2 users', async () => {
    const res = await request(app).get('/users');
    expect(res.body).toHaveLength(2);
  });

  it('first user has the expected field values', async () => {
    const res = await request(app).get('/users');
    const alice = res.body.find((u) => u.name === 'Alice');
    expect(alice).toMatchObject({
      id: 1,
      name: 'Alice',
      email: 'alice@example.com',
    });
  });

  it('second user has the expected field values', async () => {
    const res = await request(app).get('/users');
    const bob = res.body.find((u) => u.name === 'Bob');
    expect(bob).toMatchObject({
      id: 2,
      name: 'Bob',
      email: 'bob@example.com',
    });
  });

  it('all user IDs are unique', async () => {
    const res = await request(app).get('/users');
    const ids = res.body.map((u) => u.id);
    const uniqueIds = new Set(ids);
    expect(uniqueIds.size).toBe(ids.length);
  });

  it('all user IDs are positive integers', async () => {
    const res = await request(app).get('/users');
    res.body.forEach((user) => {
      expect(Number.isInteger(user.id)).toBe(true);
      expect(user.id).toBeGreaterThan(0);
    });
  });
});

// ─── 2. Response-schema tests ────────────────────────────────────────────────

describe('GET /users — response schema', () => {
  let app;
  let res;

  beforeAll(async () => {
    app = buildNominalApp();
    res = await request(app).get('/users');
  });

  it('response body is a JSON array', () => {
    expect(Array.isArray(res.body)).toBe(true);
  });

  it('every user has exactly the required keys: id, name, email', () => {
    res.body.forEach((user) => {
      expect(Object.keys(user).sort()).toEqual(['email', 'id', 'name']);
    });
  });

  it('"id" is a positive integer on every user', () => {
    res.body.forEach((user) => {
      expect(typeof user.id).toBe('number');
      expect(Number.isInteger(user.id)).toBe(true);
      expect(user.id).toBeGreaterThan(0);
    });
  });

  it('"name" is a non-empty string on every user', () => {
    res.body.forEach((user) => {
      expect(typeof user.name).toBe('string');
      expect(user.name.trim().length).toBeGreaterThan(0);
    });
  });

  it('"email" is a valid-format string on every user', () => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    res.body.forEach((user) => {
      expect(typeof user.email).toBe('string');
      expect(emailRegex.test(user.email)).toBe(true);
    });
  });

  it('passes the full validateUserSchema() contract for every user', () => {
    res.body.forEach((user) => {
      const violations = validateUserSchema(user);
      // Attach the list so Jest's failure message is actionable
      expect(violations).toEqual([]);
    });
  });

  it('entire body matches the inline Jest snapshot', () => {
    expect(res.body).toMatchInlineSnapshot(`
      [
        {
          "email": "alice@example.com",
          "id": 1,
          "name": "Alice",
        },
        {
          "email": "bob@example.com",
          "id": 2,
          "name": "Bob",
        },
      ]
    `);
  });
});

// ─── 3. HTTP-semantics tests ─────────────────────────────────────────────────

describe('GET /users — HTTP semantics', () => {
  let app;

  beforeAll(() => {
    app = buildNominalApp();
  });

  it('Content-Type header includes application/json', async () => {
    const res = await request(app).get('/users');
    expect(res.headers['content-type']).toMatch(/application\/json/);
  });

  it('is idempotent — two sequential calls return identical bodies', async () => {
    const [first, second] = await Promise.all([
      request(app).get('/users'),
      request(app).get('/users'),
    ]);
    expect(first.body).toEqual(second.body);
  });

  it('POST /users returns 404 (method not registered)', async () => {
    const res = await request(app).post('/users').send({ name: 'Charlie' });
    expect(res.statusCode).toBe(404);
  });

  it('PUT /users returns 404 (method not registered)', async () => {
    const res = await request(app).put('/users');
    expect(res.statusCode).toBe(404);
  });

  it('DELETE /users returns 404 (method not registered)', async () => {
    const res = await request(app).delete('/users');
    expect(res.statusCode).toBe(404);
  });

  it('unknown route /unknown returns 404', async () => {
    const res = await request(app).get('/unknown');
    expect(res.statusCode).toBe(404);
  });
});

// ─── 4. Error-handling tests ─────────────────────────────────────────────────

describe('GET /users — error handling', () => {
  /**
   * These tests use buildErrorApp() so we can control exactly what the route
   * handler throws, keeping them fully decoupled from the nominal app.
   */

  it('returns HTTP 500 when the handler calls next(err)', async () => {
    const app = buildErrorApp();
    const res = await request(app).get('/users');
    expect(res.statusCode).toBe(500);
  });

  it('error response body contains an "error" key', async () => {
    const app = buildErrorApp();
    const res = await request(app).get('/users');
    expect(res.body).toHaveProperty('error');
  });

  it('error response body contains a "message" key', async () => {
    const app = buildErrorApp();
    const res = await request(app).get('/users');
    expect(res.body).toHaveProperty('message');
  });

  it('error "message" echoes the thrown error text', async () => {
    const app = buildErrorApp();
    const res = await request(app).get('/users');
    expect(res.body.message).toBe('Database connection lost');
  });

  it('error response Content-Type is still application/json', async () => {
    const app = buildErrorApp();
    const res = await request(app).get('/users');
    expect(res.headers['content-type']).toMatch(/application\/json/);
  });

  it('nominal app does NOT return 500 under normal conditions', async () => {
    const app = buildNominalApp();
    const res = await request(app).get('/users');
    expect(res.statusCode).not.toBe(500);
  });

  it('mocked route — handler that returns 503 is forwarded correctly', async () => {
    const app = express();
    app.get('/users', (_req, res) => res.status(503).json({ error: 'Service Unavailable' }));

    const res = await request(app).get('/users');
    expect(res.statusCode).toBe(503);
    expect(res.body.error).toBe('Service Unavailable');
  });
});

