/**
 * Tests for the /users endpoint in app.js
 *
 * Run with:  npm test
 * Requires:  jest, supertest  (npm install --save-dev jest supertest)
 */

const request = require('supertest');
const app     = require('./app');

// ─── Schema validator ────────────────────────────────────────────────────────
/**
 * Validates that a value conforms to a plain schema descriptor.
 *
 * Supported descriptors
 *   { type: 'array',  items: <descriptor> }
 *   { type: 'object', properties: { key: <descriptor> }, required: [key, …] }
 *   { type: 'string' | 'number' | 'boolean' }
 *
 * Returns { valid: true } or { valid: false, errors: string[] }.
 */
function validateSchema(value, schema, path = 'root') {
  const errors = [];

  function check(val, sch, p) {
    if (sch.type === 'array') {
      if (!Array.isArray(val)) {
        errors.push(`${p}: expected array, got ${typeof val}`);
        return;
      }
      if (sch.items) {
        val.forEach((item, i) => check(item, sch.items, `${p}[${i}]`));
      }
      return;
    }

    if (sch.type === 'object') {
      if (typeof val !== 'object' || val === null || Array.isArray(val)) {
        errors.push(`${p}: expected object, got ${Array.isArray(val) ? 'array' : typeof val}`);
        return;
      }
      (sch.required || []).forEach(key => {
        if (!(key in val)) errors.push(`${p}: missing required property "${key}"`);
      });
      Object.entries(sch.properties || {}).forEach(([key, subSch]) => {
        if (key in val) check(val[key], subSch, `${p}.${key}`);
      });
      return;
    }

    // Primitives
    if (typeof val !== sch.type) {
      errors.push(`${p}: expected ${sch.type}, got ${typeof val}`);
    }
  }

  check(value, schema, path);
  return errors.length === 0
    ? { valid: true }
    : { valid: false, errors };
}

// ─── Expected response schema ─────────────────────────────────────────────────
const USER_SCHEMA = {
  type: 'array',
  items: {
    type: 'object',
    required: ['id', 'name', 'email'],
    properties: {
      id:    { type: 'number'  },
      name:  { type: 'string' },
      email: { type: 'string' },
    },
  },
};

// ─── Test suite ───────────────────────────────────────────────────────────────
describe('GET /users', () => {

  // ── Happy path ──────────────────────────────────────────────────────────────
  describe('Happy path', () => {

    test('responds with HTTP 200', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toBe(200);
    });

    test('responds with JSON content-type', async () => {
      const res = await request(app).get('/users');
      expect(res.headers['content-type']).toMatch(/application\/json/);
    });

    test('returns an array', async () => {
      const res = await request(app).get('/users');
      expect(Array.isArray(res.body)).toBe(true);
    });

    test('returns at least one user', async () => {
      const res = await request(app).get('/users');
      expect(res.body.length).toBeGreaterThan(0);
    });

    test('returns the expected seed users', async () => {
      const res = await request(app).get('/users');
      expect(res.body).toEqual(
        expect.arrayContaining([
          expect.objectContaining({ id: 1, name: 'Alice', email: 'alice@example.com' }),
          expect.objectContaining({ id: 2, name: 'Bob',   email: 'bob@example.com'   }),
        ])
      );
    });

    test('every user has a unique id', async () => {
      const res = await request(app).get('/users');
      const ids = res.body.map(u => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });

    test('every user email is a valid email address', async () => {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const res = await request(app).get('/users');
      res.body.forEach(user => {
        expect(user.email).toMatch(emailRegex);
      });
    });

  });

  // ── Response-shape / schema ─────────────────────────────────────────────────
  describe('Response schema', () => {

    test('response body matches the USER_SCHEMA', async () => {
      const res    = await request(app).get('/users');
      const result = validateSchema(res.body, USER_SCHEMA);
      // Surface every schema violation as part of the failure message
      expect(result.errors ?? []).toEqual([]);
      expect(result.valid).toBe(true);
    });

    test('each user object contains exactly the fields: id, name, email', async () => {
      const ALLOWED_KEYS = new Set(['id', 'name', 'email']);
      const res = await request(app).get('/users');
      res.body.forEach((user, i) => {
        const keys = Object.keys(user);
        // No extra fields
        keys.forEach(key => {
          expect(ALLOWED_KEYS).toContain(key);   // no unexpected field on user[i]
        });
        // No missing fields
        ALLOWED_KEYS.forEach(key => {
          expect(keys).toContain(key);           // required field present on user[i]
        });
      });
    });

    test('id is a positive integer', async () => {
      const res = await request(app).get('/users');
      res.body.forEach(user => {
        expect(typeof user.id).toBe('number');
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    test('name is a non-empty string', async () => {
      const res = await request(app).get('/users');
      res.body.forEach(user => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim().length).toBeGreaterThan(0);
      });
    });

    test('email is a non-empty string', async () => {
      const res = await request(app).get('/users');
      res.body.forEach(user => {
        expect(typeof user.email).toBe('string');
        expect(user.email.trim().length).toBeGreaterThan(0);
      });
    });

  });

  // ── Error-handling / edge cases ─────────────────────────────────────────────
  describe('Error handling', () => {

    test('returns 404 for /users/ (trailing slash variant)', async () => {
      // Express does not mount a handler for "/users/" so it should 404
      const res = await request(app).get('/users/');
      expect(res.statusCode).toBe(404);
    });

    test('returns 404 for an unknown sub-path /users/unknown', async () => {
      const res = await request(app).get('/users/unknown');
      expect(res.statusCode).toBe(404);
    });

    test('returns 404 for a numeric id path /users/1', async () => {
      // No individual-user route is defined
      const res = await request(app).get('/users/1');
      expect(res.statusCode).toBe(404);
    });

    test('ignores unknown query parameters and still returns 200', async () => {
      const res = await request(app).get('/users?foo=bar&limit=999');
      expect(res.statusCode).toBe(200);
    });

    test('does not accept POST /users (405 or 404)', async () => {
      const res = await request(app).post('/users').send({ name: 'Eve' });
      expect([404, 405]).toContain(res.statusCode);
    });

    test('does not accept PUT /users (405 or 404)', async () => {
      const res = await request(app).put('/users').send({});
      expect([404, 405]).toContain(res.statusCode);
    });

    test('does not accept DELETE /users (405 or 404)', async () => {
      const res = await request(app).delete('/users');
      expect([404, 405]).toContain(res.statusCode);
    });

    test('handles HEAD /users without a body', async () => {
      // Express answers HEAD automatically when GET is defined
      const res = await request(app).head('/users');
      expect(res.statusCode).toBe(200);
      // HEAD responses must not carry a body
      expect(res.text).toBeFalsy();
    });

    test('simulated DB failure: /users returns 500 when handler throws', async () => {
      // Temporarily replace the route handler to simulate an internal error.
      // We use a fresh mini-Express app that wraps the real router but
      // overrides /users so we can test the error-response contract without
      // modifying app.js itself.
      const express        = require('express');
      const brokenApp      = express();

      brokenApp.get('/users', (_req, res, next) => {
        next(new Error('Simulated database failure'));
      });

      // Generic error handler
      brokenApp.use((err, _req, res, _next) => {
        res.status(500).json({ error: err.message });
      });

      const res = await request(brokenApp).get('/users');
      expect(res.statusCode).toBe(500);
      expect(res.body).toHaveProperty('error');
      expect(typeof res.body.error).toBe('string');
    });

    test('simulated DB failure: error response body has an "error" string field', async () => {
      const express   = require('express');
      const errorApp  = express();

      errorApp.get('/users', (_req, _res, next) => {
        next(new Error('Connection timeout'));
      });
      errorApp.use((err, _req, res, _next) => {
        res.status(500).json({ error: err.message });
      });

      const res = await request(errorApp).get('/users');
      expect(res.body.error).toBe('Connection timeout');
    });

  });

});

// ─── Sanity-check the schema validator itself ─────────────────────────────────
describe('validateSchema (internal utility)', () => {

  test('passes a valid user array', () => {
    const result = validateSchema(
      [{ id: 1, name: 'Alice', email: 'alice@example.com' }],
      USER_SCHEMA
    );
