/**
 * Tests for the /users endpoint in app.js
 *
 * Test suites:
 *  1. Happy Path          — successful responses, correct data, status codes
 *  2. Response Schema     — shape, types, and required fields of every returned object
 *  3. Error Handling      — 404s, bad methods, malformed requests
 *  4. HTTP Semantics      — headers, content-type, caching hints
 */

const request = require('supertest');
const app     = require('./app');

// ---------------------------------------------------------------------------
// Helpers / shared schema validator
// ---------------------------------------------------------------------------

/**
 * Asserts that a single user object satisfies the expected schema:
 *   { id: number, name: string, email: string }
 *
 * Keeping this as a plain function (rather than a JSON-schema library) keeps
 * the test file dependency-free beyond supertest + jest.
 *
 * @param {unknown} user  - The value to validate.
 */
function assertUserSchema(user) {
  // Must be a plain object, not null / array / primitive
  expect(user).not.toBeNull();
  expect(typeof user).toBe('object');
  expect(Array.isArray(user)).toBe(false);

  // Required keys are present
  expect(user).toHaveProperty('id');
  expect(user).toHaveProperty('name');
  expect(user).toHaveProperty('email');

  // Correct primitive types
  expect(typeof user.id).toBe('number');
  expect(typeof user.name).toBe('string');
  expect(typeof user.email).toBe('string');

  // Values are not empty / NaN
  expect(user.id).toBeGreaterThan(0);
  expect(Number.isInteger(user.id)).toBe(true);
  expect(user.name.trim().length).toBeGreaterThan(0);
  expect(user.email.trim().length).toBeGreaterThan(0);

  // No extra keys leak into the response (strict shape guard)
  const allowedKeys = new Set(['id', 'name', 'email']);
  Object.keys(user).forEach((key) =>
    expect(allowedKeys).toContain(key)
  );
}

/**
 * Minimal RFC-5322–style e-mail validator used in schema tests.
 * Intentionally simple: local@domain.tld
 */
function isValidEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

// ---------------------------------------------------------------------------
// 1. Happy Path
// ---------------------------------------------------------------------------

describe('GET /users — happy path', () => {
  let response;

  // Share a single request across all assertions in this suite for efficiency
  beforeAll(async () => {
    response = await request(app).get('/users');
  });

  test('responds with HTTP 200 OK', () => {
    expect(response.status).toBe(200);
  });

  test('returns a JSON array', () => {
    expect(Array.isArray(response.body)).toBe(true);
  });

  test('returns at least one user', () => {
    expect(response.body.length).toBeGreaterThan(0);
  });

  test('returns exactly the seeded users (Alice and Bob)', () => {
    const names = response.body.map((u) => u.name);
    expect(names).toContain('Alice');
    expect(names).toContain('Bob');
    expect(response.body).toHaveLength(2);
  });

  test('Alice has the correct id and e-mail', () => {
    const alice = response.body.find((u) => u.name === 'Alice');
    expect(alice).toBeDefined();
    expect(alice.id).toBe(1);
    expect(alice.email).toBe('alice@example.com');
  });

  test('Bob has the correct id and e-mail', () => {
    const bob = response.body.find((u) => u.name === 'Bob');
    expect(bob).toBeDefined();
    expect(bob.id).toBe(2);
    expect(bob.email).toBe('bob@example.com');
  });

  test('user ids are unique', () => {
    const ids = response.body.map((u) => u.id);
    const uniqueIds = new Set(ids);
    expect(uniqueIds.size).toBe(ids.length);
  });

  test('user list is ordered by id ascending', () => {
    const ids = response.body.map((u) => u.id);
    const sorted = [...ids].sort((a, b) => a - b);
    expect(ids).toEqual(sorted);
  });
});

// ---------------------------------------------------------------------------
// 2. Response Schema
// ---------------------------------------------------------------------------

describe('GET /users — response schema', () => {
  let users;

  beforeAll(async () => {
    const res = await request(app).get('/users');
    users = res.body;
  });

  test('every user object satisfies the required schema', () => {
    users.forEach((user) => assertUserSchema(user));
  });

  test('every id is a positive integer', () => {
    users.forEach((user) => {
      expect(Number.isInteger(user.id)).toBe(true);
      expect(user.id).toBeGreaterThan(0);
    });
  });

  test('every name is a non-empty string', () => {
    users.forEach((user) => {
      expect(typeof user.name).toBe('string');
      expect(user.name.trim().length).toBeGreaterThan(0);
    });
  });

  test('every email is a non-empty string', () => {
    users.forEach((user) => {
      expect(typeof user.email).toBe('string');
      expect(user.email.trim().length).toBeGreaterThan(0);
    });
  });

  test('every email matches a valid e-mail format', () => {
    users.forEach((user) => {
      expect(isValidEmail(user.email)).toBe(true);
    });
  });

  test('no user contains extra / undocumented fields', () => {
    const allowedKeys = ['id', 'name', 'email'];
    users.forEach((user) => {
      Object.keys(user).forEach((key) => {
        expect(allowedKeys).toContain(key);
      });
    });
  });

  test('response body is an array, not a wrapped object', () => {
    // Guard against accidental { data: [...] } or { users: [...] } wrappers
    expect(Array.isArray(users)).toBe(true);
  });

  test('full snapshot of the response body shape', () => {
    // Jest snapshot: run with --updateSnapshot to regenerate after intentional changes
    expect(users).toMatchSnapshot();
  });
});

// ---------------------------------------------------------------------------
// 3. Error Handling
// ---------------------------------------------------------------------------

describe('GET /users — error handling', () => {
  test('unknown route returns 404', async () => {
    const res = await request(app).get('/users/nonexistent-path');
    expect(res.status).toBe(404);
  });

  test('deeply nested unknown route returns 404', async () => {
    const res = await request(app).get('/users/1/profile/avatar');
    expect(res.status).toBe(404);
  });

  test('POST /users returns 404 (method not defined)', async () => {
    // The app does not define POST /users; Express default is 404
    const res = await request(app).post('/users').send({ name: 'Charlie' });
    expect(res.status).toBe(404);
  });

  test('PUT /users returns 404 (method not defined)', async () => {
    const res = await request(app).put('/users').send({ id: 1, name: 'Updated' });
    expect(res.status).toBe(404);
  });

  test('DELETE /users returns 404 (method not defined)', async () => {
    const res = await request(app).delete('/users');
    expect(res.status).toBe(404);
  });

  test('PATCH /users returns 404 (method not defined)', async () => {
    const res = await request(app).patch('/users').send({ name: 'X' });
    expect(res.status).toBe(404);
  });

  test('completely unknown top-level route returns 404', async () => {
    const res = await request(app).get('/does-not-exist');
    expect(res.status).toBe(404);
  });

  test('query parameters do not break the /users endpoint', async () => {
    // The current implementation ignores query params; it must still return 200
    const res = await request(app).get('/users?page=99&limit=0&foo=bar');
    expect(res.status).toBe(200);
    expect(Array.isArray(res.body)).toBe(true);
  });
});

// ---------------------------------------------------------------------------
// 4. HTTP Semantics
// ---------------------------------------------------------------------------

describe('GET /users — HTTP semantics & headers', () => {
  let response;

  beforeAll(async () => {
    response = await request(app).get('/users');
  });

  test('Content-Type is application/json', () => {
    expect(response.headers['content-type']).toMatch(/application\/json/);
  });

  test('response body can be parsed as valid JSON', () => {
    // supertest already parses it; confirm the raw text round-trips cleanly
    expect(() => JSON.parse(JSON.stringify(response.body))).not.toThrow();
  });

  test('HEAD /users returns 200 with no body', async () => {
    const res = await request(app).head('/users');
    // Express automatically handles HEAD for defined GET routes
    expect(res.status).toBe(200);
    expect(res.text).toBeFalsy(); // HEAD must have no response body
  });

  test('response is not empty (Content-Length or Transfer-Encoding present)', () => {
    const hasLength   = 'content-length' in response.headers;
    const hasEncoding = 'transfer-encoding' in response.headers;
    expect(hasLength || hasEncoding).toBe(true);
  });

  test('/health sibling route still returns 200 (no cross-route regression)', async () => {
    const res = await request(app).get('/health');
    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('status', 'ok');
  });
});

