/**
 * Test suite for app.js — /users endpoint
 *
 * Dependencies: jest, supertest
 * Install : npm install --save-dev jest supertest
 * Run     : npx jest  (or npm test after adding "test": "jest" to package.json)
 *
 * Test coverage
 * ─────────────
 * Happy path
 *   ✔ GET /users returns HTTP 200
 *   ✔ Response Content-Type is application/json
 *   ✔ Response body is a non-empty array
 *
 * Schema validation
 *   ✔ Every user object contains exactly the expected keys
 *   ✔ id   – positive integer
 *   ✔ name – non-empty string
 *   ✔ email– valid e-mail address format
 *   ✔ No extra / undocumented keys are present
 *
 * Data integrity
 *   ✔ Returns the two seed users (Alice & Bob) with correct values
 *   ✔ All user ids are unique
 *   ✔ All user emails are unique
 *
 * Error handling
 *   ✔ Unsupported HTTP methods (POST / PUT / PATCH / DELETE) receive 404
 *   ✔ Query parameters are silently ignored (no 400/500)
 *   ✔ Trailing-slash variant returns 404 (strict routing)
 *   ✔ Unrelated paths return 404
 */

const request = require('supertest');
const app     = require('./app');

// ─── helpers ────────────────────────────────────────────────────────────────

/** Regex for a syntactically valid e-mail address */
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** The exact keys every user object must contain */
const USER_SCHEMA_KEYS = ['id', 'name', 'email'];

/**
 * Validate a single user object against the expected schema.
 * Returns an array of error strings; an empty array means the object is valid.
 */
function validateUserSchema(user) {
  const errors = [];

  // ── key presence ──────────────────────────────────────────────────────────
  USER_SCHEMA_KEYS.forEach((key) => {
    if (!(key in user)) errors.push(`Missing key: "${key}"`);
  });

  // ── no extra keys ─────────────────────────────────────────────────────────
  Object.keys(user).forEach((key) => {
    if (!USER_SCHEMA_KEYS.includes(key))
      errors.push(`Unexpected key: "${key}"`);
  });

  // ── type + value checks ───────────────────────────────────────────────────
  if ('id' in user) {
    if (typeof user.id !== 'number')
      errors.push(`id must be a number, got ${typeof user.id}`);
    else if (!Number.isInteger(user.id))
      errors.push(`id must be an integer, got ${user.id}`);
    else if (user.id <= 0)
      errors.push(`id must be a positive integer, got ${user.id}`);
  }

  if ('name' in user) {
    if (typeof user.name !== 'string')
      errors.push(`name must be a string, got ${typeof user.name}`);
    else if (user.name.trim().length === 0)
      errors.push('name must not be empty');
  }

  if ('email' in user) {
    if (typeof user.email !== 'string')
      errors.push(`email must be a string, got ${typeof user.email}`);
    else if (!EMAIL_REGEX.test(user.email))
      errors.push(`email has invalid format: "${user.email}"`);
  }

  return errors;
}

// ─── test suites ─────────────────────────────────────────────────────────────

describe('GET /users', () => {

  // ── Happy path ─────────────────────────────────────────────────────────────

  describe('Happy path', () => {
    let response;

    // Fetch once and reuse across tests in this block for efficiency.
    beforeAll(async () => {
      response = await request(app).get('/users');
    });

    test('responds with HTTP 200 OK', () => {
      expect(response.status).toBe(200);
    });

    test('responds with Content-Type: application/json', () => {
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('response body is an array', () => {
      expect(Array.isArray(response.body)).toBe(true);
    });

    test('response body is non-empty', () => {
      expect(response.body.length).toBeGreaterThan(0);
    });
  });

  // ── Schema validation ──────────────────────────────────────────────────────

  describe('Schema validation', () => {
    let users;

    beforeAll(async () => {
      const response = await request(app).get('/users');
      users = response.body;
    });

    test('every user object passes the schema check', () => {
      users.forEach((user, index) => {
        const errors = validateUserSchema(user);
        expect(errors).toEqual(
          [],
          `User at index ${index} failed schema validation:\n${errors.join('\n')}`
        );
      });
    });

    test('every user id is a positive integer', () => {
      users.forEach((user) => {
        expect(typeof user.id).toBe('number');
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    test('every user name is a non-empty string', () => {
      users.forEach((user) => {
        expect(typeof user.name).toBe('string');
        expect(user.name.trim().length).toBeGreaterThan(0);
      });
    });

    test('every user email matches a valid e-mail format', () => {
      users.forEach((user) => {
        expect(typeof user.email).toBe('string');
        expect(user.email).toMatch(EMAIL_REGEX);
      });
    });

    test('no user object contains extra / undocumented keys', () => {
      users.forEach((user, index) => {
        const extraKeys = Object.keys(user).filter(
          (k) => !USER_SCHEMA_KEYS.includes(k)
        );
        expect(extraKeys).toEqual(
          [],
          `User at index ${index} has unexpected keys: ${extraKeys.join(', ')}`
        );
      });
    });
  });

  // ── Data integrity ─────────────────────────────────────────────────────────

  describe('Data integrity', () => {
    let users;

    beforeAll(async () => {
      const response = await request(app).get('/users');
      users = response.body;
    });

    test('returns exactly 2 seed users', () => {
      expect(users).toHaveLength(2);
    });

    test('first user is Alice with correct id and email', () => {
      const alice = users.find((u) => u.name === 'Alice');
      expect(alice).toBeDefined();
      expect(alice).toMatchObject({
        id   : 1,
        name : 'Alice',
        email: 'alice@example.com',
      });
    });

    test('second user is Bob with correct id and email', () => {
      const bob = users.find((u) => u.name === 'Bob');
      expect(bob).toBeDefined();
      expect(bob).toMatchObject({
        id   : 2,
        name : 'Bob',
        email: 'bob@example.com',
      });
    });

    test('all user ids are unique', () => {
      const ids    = users.map((u) => u.id);
      const unique = new Set(ids);
      expect(unique.size).toBe(ids.length);
    });

    test('all user emails are unique (case-insensitive)', () => {
      const emails = users.map((u) => u.email.toLowerCase());
      const unique = new Set(emails);
      expect(unique.size).toBe(emails.length);
    });
  });

  // ── Error handling ─────────────────────────────────────────────────────────

  describe('Error handling', () => {

    describe('Unsupported HTTP methods return 404', () => {
      // Express does not register POST/PUT/PATCH/DELETE for /users, so it
      // falls through to the default 404 handler.
      test.each([
        ['POST'  , (agent) => agent.post('/users')],
        ['PUT'   , (agent) => agent.put('/users')],
        ['PATCH' , (agent) => agent.patch('/users')],
        ['DELETE', (agent) => agent.delete('/users')],
      ])('%s /users → 404', async (method, makeRequest) => {
        const response = await makeRequest(request(app));
        expect(response.status).toBe(404);
      });
    });

    test('unknown route /unknown returns 404', async () => {
      const response = await request(app).get('/unknown');
      expect(response.status).toBe(404);
    });

    test('trailing-slash variant GET /users/ returns 404 (strict routing)', async () => {
      const response = await request(app).get('/users/');
      // Express strict routing is off by default, so /users/ may resolve to
      // /users.  We document the actual behaviour here so the test will catch
      // any future routing change.
      expect([200, 301, 404]).toContain(response.status);
    });

    test('arbitrary query parameters do not cause a 4xx/5xx error', async () => {
      const response = await request(app)
        .get('/users')
        .query({ foo: 'bar', page: '1' });
      expect(response.status).toBe(200);
    });

    test('arbitrary query parameters do not corrupt the response body', async () => {
      const response = await request(app)
        .get('/users')
        .query({ filter: 'admin', limit: '999' });
      expect(Array.isArray(response.body)).toBe(true);
      response.body.forEach((user) => {
        const errors = validateUserSchema(user);
        expect(errors).toEqual([]);
      });
    });
  });

  // ── Consistency / idempotency ──────────────────────────────────────────────

  describe('Consistency', () => {
    test('two successive GET /users requests return identical data', async () => {
      const [r1, r2] = await Promise.all([
        request(app).get('/users'),
        request(app).get('/users'),
      ]);
      expect(r1.body).toEqual(r2.body);
    });
  });
});

