/**
 * Minimal Express shim — supports the subset used by app.js:
 *   app.get(path, handler)
 *   app.listen(port, cb)
 *   app.use(middleware)       (no-op for now)
 *   module.exports = app
 *
 * res  : json(data), status(code), send(body), set(h,v)
 * req  : method, url, headers, params (from named segments), query
 */
'use strict';
const http = require('http');
const url  = require('url');

function express() {
  const routes = [];          // { method, pattern, keys, handler }
  let server   = null;

  // ── route matching helpers ──────────────────────────────────────────────
  function compile(path) {
    const keys = [];
    const src  = path
      .replace(/\//g, '\\/')
      .replace(/:([^/]+)/g, (_, k) => { keys.push(k); return '([^/]+)'; });
    return { re: new RegExp('^' + src + '\\/?$'), keys };
  }

  function parseQuery(raw) {
    const q = {};
    if (!raw) return q;
    raw.replace(/^[?]/, '').split('&').forEach(pair => {
      const [k, v] = pair.split('=');
      if (k) q[decodeURIComponent(k)] = decodeURIComponent(v || '');
    });
    return q;
  }

  // ── request/response factories ─────────────────────────────────────────
  function makeRes(nodeRes) {
    let statusCode = 200;
    const res = {
      _headers: {},
      status(code) { statusCode = code; return res; },
      set(header, value) { res._headers[header.toLowerCase()] = value; return res; },
      json(data) {
        const body = JSON.stringify(data);
        nodeRes.writeHead(statusCode, {
          'Content-Type': 'application/json',
          ...res._headers,
        });
        nodeRes.end(body);
      },
      send(body) {
        const isObj = typeof body === 'object' && body !== null;
        nodeRes.writeHead(statusCode, {
          'Content-Type': isObj ? 'application/json' : 'text/plain',
          ...res._headers,
        });
        nodeRes.end(isObj ? JSON.stringify(body) : String(body));
      },
    };
    return res;
  }

  function makeReq(nodeReq, params, query) {
    return Object.assign(nodeReq, { params, query });
  }

  // ── app object ─────────────────────────────────────────────────────────
  function app(nodeReq, nodeRes) {
    const parsed   = url.parse(nodeReq.url);
    const pathname = parsed.pathname;
    const query    = parseQuery(parsed.query);
    const method   = nodeReq.method.toUpperCase();

    for (const route of routes) {
      if (route.method !== method && route.method !== 'ALL') continue;
      const m = pathname.match(route.re);
      if (!m) continue;
      const params = {};
      route.keys.forEach((k, i) => { params[k] = m[i + 1]; });
      return route.handler(makeReq(nodeReq, params, query), makeRes(nodeRes));
    }
    // 404 fallback
    nodeRes.writeHead(404, { 'Content-Type': 'application/json' });
    nodeRes.end(JSON.stringify({ error: 'Not Found' }));
  }

  function addRoute(method, path, handler) {
    const { re, keys } = compile(path);
    routes.push({ method: method.toUpperCase(), pattern: path, re, keys, handler });
  }

  app.get    = (path, handler) => addRoute('GET',    path, handler);
  app.post   = (path, handler) => addRoute('POST',   path, handler);
  app.put    = (path, handler) => addRoute('PUT',    path, handler);
  app.delete = (path, handler) => addRoute('DELETE', path, handler);
  app.use    = () => {};          // middleware no-op

  app.listen = (port, cb) => {
    server = http.createServer(app);
    server.listen(port, cb);
    return server;
  };

  app._routes = routes;
  return app;
}

module.exports = express;

