/**
 * app.test.js
 *
 * Unit / integration tests for the Express application defined in app.js.
 * Focus: GET /users endpoint (happy path, error handling, schema validation).
 *
 * Run with:  npm test
 * Requires:  npm install  (jest, supertest, express)
 */

const request = require('supertest');
const app     = require('./app');

// ---------------------------------------------------------------------------
// Helpers / shared fixtures
// ---------------------------------------------------------------------------

/**
 * Validates that a single user object matches the expected schema.
 *
 * Expected shape:
 *   { id: <positive integer>, name: <non-empty string>, email: <valid e-mail> }
 */
function expectValidUserSchema(user) {
  // id  — must be a positive integer
  expect(user).toHaveProperty('id');
  expect(typeof user.id).toBe('number');
  expect(Number.isInteger(user.id)).toBe(true);
  expect(user.id).toBeGreaterThan(0);

  // name — must be a non-empty string
  expect(user).toHaveProperty('name');
  expect(typeof user.name).toBe('string');
  expect(user.name.trim().length).toBeGreaterThan(0);

  // email — must be a non-empty string containing exactly one '@'
  expect(user).toHaveProperty('email');
  expect(typeof user.email).toBe('string');
  expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
}

// ---------------------------------------------------------------------------
// GET /users
// ---------------------------------------------------------------------------

describe('GET /users', () => {

  // ── Happy path ────────────────────────────────────────────────────────────

  describe('Happy path', () => {
    let response;

    // Make a single request and reuse it across the happy-path assertions so
    // we only hit the server once.
    beforeAll(async () => {
      response = await request(app).get('/users');
    });

    test('responds with HTTP 200 OK', () => {
      expect(response.status).toBe(200);
    });

    test('responds with Content-Type application/json', () => {
      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    test('response body is a non-empty array', () => {
      expect(Array.isArray(response.body)).toBe(true);
      expect(response.body.length).toBeGreaterThan(0);
    });

    test('returns exactly two users', () => {
      expect(response.body).toHaveLength(2);
    });

    test('first user has correct data', () => {
      const [alice] = response.body;
      expect(alice).toEqual({
        id:    1,
        name:  'Alice',
        email: 'alice@example.com',
      });
    });

    test('second user has correct data', () => {
      const [, bob] = response.body;
      expect(bob).toEqual({
        id:    2,
        name:  'Bob',
        email: 'bob@example.com',
      });
    });

    test('users are returned in ascending id order', () => {
      const ids = response.body.map((u) => u.id);
      const sorted = [...ids].sort((a, b) => a - b);
      expect(ids).toEqual(sorted);
    });

    test('every user id is unique', () => {
      const ids = response.body.map((u) => u.id);
      const uniqueIds = new Set(ids);
      expect(uniqueIds.size).toBe(ids.length);
    });

    test('every user email is unique', () => {
      const emails = response.body.map((u) => u.email);
      const uniqueEmails = new Set(emails);
      expect(uniqueEmails.size).toBe(emails.length);
    });
  });

  // ── Schema validation ─────────────────────────────────────────────────────

  describe('Response schema', () => {
    let users;

    beforeAll(async () => {
      const response = await request(app).get('/users');
      users = response.body;
    });

    test('response body contains only the expected top-level fields per user', () => {
      const ALLOWED_KEYS = new Set(['id', 'name', 'email']);
      users.forEach((user) => {
        const actualKeys = Object.keys(user);
        actualKeys.forEach((key) => {
          expect(ALLOWED_KEYS.has(key)).toBe(true);
        });
        // All three required keys must be present
        expect(actualKeys).toHaveLength(ALLOWED_KEYS.size);
      });
    });

    test('every user in the array passes schema validation', () => {
      users.forEach((user) => {
        expectValidUserSchema(user);
      });
    });

    test('id is a number, not a string or null', () => {
      users.forEach((user) => {
        expect(typeof user.id).toBe('number');
        expect(user.id).not.toBeNaN();
      });
    });

    test('name is a string, not null or undefined', () => {
      users.forEach((user) => {
        expect(typeof user.name).toBe('string');
      });
    });

    test('email matches standard e-mail format', () => {
      const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      users.forEach((user) => {
        expect(user.email).toMatch(EMAIL_RE);
      });
    });

    test('response matches full snapshot', async () => {
      // Jest snapshot — re-run with `--updateSnapshot` if the fixture changes.
      const response = await request(app).get('/users');
      expect(response.body).toMatchSnapshot();
    });
  });

  // ── Error handling ────────────────────────────────────────────────────────

  describe('Error handling', () => {

    test('returns 404 for an unknown route', async () => {
      const response = await request(app).get('/unknown-route');
      expect(response.status).toBe(404);
    });

    test('GET /users does not accept a request body and still returns 200', async () => {
      // HTTP spec allows a body on GET, but the server should ignore it.
      const response = await request(app)
        .get('/users')
        .send({ rogue: 'payload' });
      expect(response.status).toBe(200);
      expect(Array.isArray(response.body)).toBe(true);
    });

    test('GET /users is idempotent — identical consecutive calls return the same data', async () => {
      const [first, second] = await Promise.all([
        request(app).get('/users'),
        request(app).get('/users'),
      ]);
      expect(first.status).toBe(200);
      expect(second.status).toBe(200);
      expect(first.body).toEqual(second.body);
