/**
 * app.test.js
 *
 * Jest unit tests for the /users endpoint in app.js.
 *
 * Covers:
 *  - Happy path  : correct status, body shape, and field values
 *  - Schema      : every user object matches the expected JSON schema
 *  - Error path  : graceful handling when the route throws an error
 *  - Edge cases  : Content-Type header, empty-array response, idempotency
 *
 * Run:
 *   npm install          # installs jest, supertest, express
 *   npm test             # runs jest
 */

const request = require('supertest');

// ─── Helpers ────────────────────────────────────────────────────────────────

/**
 * Lightweight schema validator – keeps the test file self-contained without
 * requiring an extra dependency such as ajv or joi.
 *
 * @param {object}  obj    – the value to validate
 * @param {object}  schema – plain descriptor: { field: expectedType, … }
 * @returns {{ valid: boolean, errors: string[] }}
 */
function validateSchema(obj, schema) {
  const errors = [];

  for (const [field, expectedType] of Object.entries(schema)) {
    if (!(field in obj)) {
      errors.push(`Missing required field: "${field}"`);
      continue;
    }
    // eslint-disable-next-line valid-typeof
    if (typeof obj[field] !== expectedType) {
      errors.push(
        `Field "${field}" expected type "${expectedType}" but got "${typeof obj[field]}"`,
      );
    }
  }

  // Flag unexpected extra fields so the schema stays strict.
  for (const key of Object.keys(obj)) {
    if (!(key in schema)) {
      errors.push(`Unexpected field: "${key}"`);
    }
  }

  return { valid: errors.length === 0, errors };
}

/** Schema every user object in the /users response must satisfy. */
const USER_SCHEMA = {
  id:    'number',
  name:  'string',
  email: 'string',
};

// ─── Test suite ─────────────────────────────────────────────────────────────

describe('GET /users', () => {
  let app;

  // Re-require app before each suite so module-level state is isolated.
  beforeEach(() => {
    // Clear the module cache so each test starts from a clean import.
    jest.resetModules();
    app = require('./app');
  });

  afterEach(() => {
    // If the app exposes a server instance, close it to avoid open handles.
    if (app.server && typeof app.server.close === 'function') {
      app.server.close();
    }
  });

  // ── Happy-path tests ──────────────────────────────────────────────────────

  describe('Happy path', () => {
    it('responds with HTTP 200', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toBe(200);
    });

    it('returns a JSON array', async () => {
      const res = await request(app).get('/users');
      expect(Array.isArray(res.body)).toBe(true);
    });

    it('returns at least one user', async () => {
      const res = await request(app).get('/users');
      expect(res.body.length).toBeGreaterThan(0);
    });

    it('returns exactly two users in the default response', async () => {
      const res = await request(app).get('/users');
      expect(res.body).toHaveLength(2);
    });

    it('contains Alice as the first user', async () => {
      const res = await request(app).get('/users');
      expect(res.body[0]).toMatchObject({
        id:    1,
        name:  'Alice',
        email: 'alice@example.com',
      });
    });

    it('contains Bob as the second user', async () => {
      const res = await request(app).get('/users');
      expect(res.body[1]).toMatchObject({
        id:    2,
        name:  'Bob',
        email: 'bob@example.com',
      });
    });

    it('returns the full expected user list', async () => {
      const res = await request(app).get('/users');
      expect(res.body).toEqual([
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob',   email: 'bob@example.com'   },
      ]);
    });

    it('each user id is a positive integer', async () => {
      const res = await request(app).get('/users');
      res.body.forEach((user) => {
        expect(typeof user.id).toBe('number');
        expect(Number.isInteger(user.id)).toBe(true);
        expect(user.id).toBeGreaterThan(0);
      });
    });

    it('each user email contains an @ symbol', async () => {
      const res = await request(app).get('/users');
      res.body.forEach((user) => {
        expect(user.email).toContain('@');
      });
    });

    it('is idempotent – two consecutive calls return the same payload', async () => {
      const first  = await request(app).get('/users');
      const second = await request(app).get('/users');
      expect(first.body).toEqual(second.body);
    });
  });

  // ── Content-Type / header tests ───────────────────────────────────────────

  describe('Response headers', () => {
    it('sets Content-Type to application/json', async () => {
      const res = await request(app).get('/users');
      expect(res.headers['content-type']).toMatch(/application\/json/);
    });

    it('does not expose sensitive server information', async () => {
      const res = await request(app).get('/users');
      // Express removes X-Powered-By when disabled; default is "Express".
      // Either way it should never leak internal stack details.
      const powered = res.headers['x-powered-by'] ?? '';
      expect(powered.toLowerCase()).not.toMatch(/version|node|internal/);
    });
  });

  // ── Schema-validation tests ───────────────────────────────────────────────

  describe('Response schema', () => {
    it('every user object has exactly the required fields (id, name, email)', async () => {
      const res = await request(app).get('/users');

      res.body.forEach((user, index) => {
        const { valid, errors } = validateSchema(user, USER_SCHEMA);
        expect(
          valid,
          `User at index ${index} failed schema validation:\n  ${errors.join('\n  ')}`,
        ).toBe(true);
      });
    });

    it('user id field is of type number', async () => {
      const res = await request(app).get('/users');
      res.body.forEach((user) => expect(typeof user.id).toBe('number'));
    });

    it('user name field is of type string', async () => {
      const res = await request(app).get('/users');
      res.body.forEach((user) => expect(typeof user.name).toBe('string'));
    });

    it('user email field is of type string', async () => {
      const res = await request(app).get('/users');
      res.body.forEach((user) => expect(typeof user.email).toBe('string'));
    });

    it('no user object contains undefined or null values', async () => {
      const res = await request(app).get('/users');
      res.body.forEach((user) => {
        Object.entries(user).forEach(([key, value]) => {
          expect(value, `Field "${key}" must not be null or undefined`).not.toBeNull();
          expect(value).not.toBeUndefined();
        });
      });
    });

    it('all user ids are unique', async () => {
      const res = await request(app).get('/users');
      const ids = res.body.map((u) => u.id);
      expect(new Set(ids).size).toBe(ids.length);
    });

    it('all user names are non-empty strings', async () => {
      const res = await request(app).get('/users');
      res.body.forEach((user) => expect(user.name.trim().length).toBeGreaterThan(0));
    });

    it('all user emails match a basic email pattern', async () => {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const res = await request(app).get('/users');
      res.body.forEach((user) => {
        expect(user.email).toMatch(emailRegex);
      });
    });
  });

  // ── Error-handling tests ──────────────────────────────────────────────────

  describe('Error handling', () => {
    it('returns 404 for an unknown route', async () => {
      const res = await request(app).get('/users/999/does-not-exist');
      expect(res.statusCode).toBe(404);
    });

    it('returns 404 for a completely unrelated route', async () => {
      const res = await request(app).get('/nonexistent');
      expect(res.statusCode).toBe(404);
    });

    it('rejects POST to /users with 404 (method not registered)', async () => {
      const res = await request(app).post('/users').send({ name: 'Eve' });
      // Express returns 404 for unregistered method+path combinations.
      expect(res.statusCode).toBe(404);
    });

    it('rejects DELETE to /users with 404', async () => {
      const res = await request(app).delete('/users');
      expect(res.statusCode).toBe(404);
    });

    it('rejects PUT to /users with 404', async () => {
      const res = await request(app).put('/users');
      expect(res.statusCode).toBe(404);
    });

    it('handles a simulated internal error and returns 500', async () => {
      // Temporarily monkey-patch res.json to throw, then restore it.
      jest.resetModules();
      const express = require('express');

      const faultyApp = express();
      faultyApp.get('/users', (_req, res) => {
        // Simulate an unhandled synchronous error inside the route handler.
        throw new Error('Simulated database failure');
      });

      // Add a minimal Express error handler so the app returns 500
      // instead of crashing (mirrors what production apps should do).
      faultyApp.use((err, _req, res, _next) => {
        res.status(500).json({ error: err.message });
      });

      const res = await request(faultyApp).get('/users');
      expect(res.statusCode).toBe(500);
      expect(res.body).toHaveProperty('error');
      expect(typeof res.body.error).toBe('string');
    });

    it('returns JSON (not HTML) even when an error handler responds with 500', async () => {
      jest.resetModules();
      const express = require('express');

      const faultyApp = express();
      faultyApp.get('/users', () => { throw new Error('oops'); });
      faultyApp.use((err, _req, res, _next) => {
        res.status(500).json({ error: err.message });
      });

      const res = await request(faultyApp).get('/users');
      expect(res.headers['content-type']).toMatch(/application\/json/);
    });
  });

  // ── Edge-case / robustness tests ──────────────────────────────────────────

  describe('Edge cases', () => {
    it('ignores unknown query parameters without error', async () => {
      const res = await request(app).get('/users?foo=bar&limit=5');
      expect(res.statusCode).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
    });

    it('handles request with Accept: application/json header', async () => {
      const res = await request(app)
        .get('/users')
        .set('Accept', 'application/json');
      expect(res.statusCode).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
    });

    it('handles request with Accept: */* header', async () => {
      const res = await request(app)
        .get('/users')
        .set('Accept', '*/*');
      expect(res.statusCode).toBe(200);
    });

    it('responds consistently regardless of User-Agent', async () => {
      const res = await request(app)
        .get('/users')
        .set('User-Agent', 'TestBot/1.0');
      expect(res.statusCode).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
    });

    it('returns an empty-array-compatible structure when route is overridden', async () => {
      // Verify the schema validator itself handles an empty array correctly.
      // (Useful for future pagination or filter scenarios.)
      const emptyUsers = [];
      emptyUsers.forEach((user) => {
        const { valid } = validateSchema(user, USER_SCHEMA);
        expect(valid).toBe(true);
      });
      // No items → no violations.
      expect(emptyUsers).toHaveLength(0);
    });
  });
});

// ─── /health sanity check (ensures other routes still work) ─────────────────

describe('GET /health (sanity check)', () => {
  let app;
  beforeEach(() => { jest.resetModules(); app = require('./app'); });

  it('responds with HTTP 200', async () => {
    const res = await request(app).get('/health');
    expect(res.statusCode).toBe(200);
  });

