 *
 * Run:
 *   npm install          # installs jest, supertest, express
 *   npm test             # runs jest
 */

const request = require('supertest');

// ─── Helpers ────────────────────────────────────────────────────────────────

/**
 * Lightweight schema validator – keeps the test file self-contained without
 * requiring an extra dependency such as ajv or joi.
 *
 * @param {object}  obj    – the value to validate
 * @param {object}  schema – plain descriptor: { field: expectedType, … }
 * @returns {{ valid: boolean, errors: string[] }}
 */
function validateSchema(obj, schema) {
  const errors = [];

  for (const [field, expectedType] of Object.entries(schema)) {
    if (!(field in obj)) {
      errors.push(`Missing required field: "${field}"`);
      continue;
    }
    // eslint-disable-next-line valid-typeof
    if (typeof obj[field] !== expectedType) {
      errors.push(
        `Field "${field}" expected type "${expectedType}" but got "${typeof obj[field]}"`,
      );
    }
  }

  // Flag unexpected extra fields so the schema stays strict.
  for (const key of Object.keys(obj)) {
    if (!(key in schema)) {
      errors.push(`Unexpected field: "${key}"`);
    }
  }

  return { valid: errors.length === 0, errors };
}

