/**
 * app.test.js
 *
 * Unit / integration tests for the /users endpoint in app.js.
 *
 * Test suite layout
 * ─────────────────
 * 1. Happy-path tests          – normal successful requests
 * 2. Response-schema tests     – shape / type validation of every field
 * 3. Error-handling tests      – 404, wrong method, malformed paths
 * 4. Edge-case / extra tests   – headers, idempotency, concurrent requests
 *
 * Dependencies
 * ────────────
 *   jest        – test runner  (npm install --save-dev jest)
 *   supertest   – HTTP assertions  (npm install --save-dev supertest)
 */

const request = require('supertest');
const app = require('./app');

// ─── helpers ──────────────────────────────────────────────────────────────────

/**
 * Validates that a single object matches the User schema.
 * Extracted into a helper so every per-item assertion is DRY and
 * the same rules are reused across multiple tests.
 *
 * Expected shape:
 *   { id: <positive integer>, name: <non-empty string>, email: <RFC-5322-ish> }
 */
function assertValidUser(user) {
  // ── id ──────────────────────────────────────────────────────────────────────
  expect(user).toHaveProperty('id');
  expect(typeof user.id).toBe('number');
  expect(Number.isInteger(user.id)).toBe(true);
  expect(user.id).toBeGreaterThan(0);

  // ── name ────────────────────────────────────────────────────────────────────
  expect(user).toHaveProperty('name');
  expect(typeof user.name).toBe('string');
  expect(user.name.trim().length).toBeGreaterThan(0);

  // ── email ───────────────────────────────────────────────────────────────────
  expect(user).toHaveProperty('email');
  expect(typeof user.email).toBe('string');
  // Basic RFC-5322 sanity check: something@something.something
  expect(user.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);

  // ── no extra, unexpected keys ────────────────────────────────────────────────
  const allowedKeys = new Set(['id', 'name', 'email']);
  Object.keys(user).forEach((key) => {
    expect(allowedKeys.has(key)).toBe(true);
  });
}

// ─── close the server after all tests so Jest can exit cleanly ───────────────
let server;
beforeAll(() => {
  // Bind to port 0 so the OS picks a free ephemeral port; avoids conflicts with
  // the hardcoded 3000 in app.js when the real server happens to be running.
  server = app.listen(0);
});
afterAll((done) => {
  server.close(done);
});

// =============================================================================
// 1. HAPPY-PATH TESTS
// =============================================================================
describe('GET /users – happy path', () => {
  let response;

  // Make one request and share it across all tests in this describe block.
  beforeAll(async () => {
    response = await request(app).get('/users');
  });

  test('responds with HTTP 200 OK', () => {
    expect(response.status).toBe(200);
  });

  test('returns JSON content-type', () => {
    expect(response.headers['content-type']).toMatch(/application\/json/);
  });

  test('response body is an array', () => {
    expect(Array.isArray(response.body)).toBe(true);
  });

  test('array is non-empty', () => {
    expect(response.body.length).toBeGreaterThan(0);
  });

  test('returns exactly 2 users', () => {
    expect(response.body).toHaveLength(2);
  });

  test('first user has correct data', () => {
    const first = response.body[0];
    expect(first.id).toBe(1);
    expect(first.name).toBe('Alice');
    expect(first.email).toBe('alice@example.com');
  });

  test('second user has correct data', () => {
    const second = response.body[1];
    expect(second.id).toBe(2);
    expect(second.name).toBe('Bob');
    expect(second.email).toBe('bob@example.com');
  });

  test('user ids are unique', () => {
    const ids = response.body.map((u) => u.id);
    const uniqueIds = new Set(ids);
    expect(uniqueIds.size).toBe(ids.length);
  });

  test('endpoint is idempotent – second request returns identical data', async () => {
    const second = await request(app).get('/users');
    expect(second.body).toEqual(response.body);
  });
});

// =============================================================================
// 2. RESPONSE-SCHEMA TESTS
// =============================================================================
describe('GET /users – response schema validation', () => {
  let users;

  beforeAll(async () => {
    const response = await request(app).get('/users');
    users = response.body;
  });

  test('every item in the array passes the User schema', () => {
    users.forEach((user) => assertValidUser(user));
  });

  test('id field is a positive integer (not a float or string)', () => {
    users.forEach((user) => {
      expect(Number.isInteger(user.id)).toBe(true);
      expect(user.id).toBeGreaterThan(0);
    });
  });

  test('name field is a non-empty trimmed string', () => {
    users.forEach((user) => {
      expect(typeof user.name).toBe('string');
      expect(user.name.trim()).toBeTruthy();
    });
  });

  test('email field matches an email pattern', () => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    users.forEach((user) => {
      expect(user.email).toMatch(emailRegex);
    });
  });

  test('no user object contains unexpected properties', () => {
    const allowedKeys = ['id', 'name', 'email'];
    users.forEach((user) => {
      const extraKeys = Object.keys(user).filter(
        (k) => !allowedKeys.includes(k)
      );
      expect(extraKeys).toHaveLength(0);
    });
  });

  test('response body matches exact snapshot', () => {
    expect(users).toMatchSnapshot();
  });

  test('full response body matches expected shape with toMatchObject', () => {
    expect(users).toMatchObject([
      { id: expect.any(Number), name: expect.any(String), email: expect.any(String) },
      { id: expect.any(Number), name: expect.any(String), email: expect.any(String) },
    ]);
  });
});

// =============================================================================
// 3. ERROR-HANDLING TESTS
// =============================================================================
describe('GET /users – error handling', () => {
  test('returns 404 for a non-existent route /user (singular)', async () => {
    const response = await request(app).get('/user');
    expect(response.status).toBe(404);
  });

  test('returns 404 for a non-existent route /users/999 (resource not found)', async () => {
    const response = await request(app).get('/users/999');
    expect(response.status).toBe(404);
  });

  test('returns 404 for completely unknown routes', async () => {
    const response = await request(app).get('/this-route-does-not-exist');
    expect(response.status).toBe(404);
  });

  test('POST /users returns 404 (method not registered)', async () => {
    const response = await request(app).post('/users').send({ name: 'Charlie' });
    expect(response.status).toBe(404);
  });

  test('PUT /users returns 404 (method not registered)', async () => {
    const response = await request(app).put('/users').send({});
    expect(response.status).toBe(404);
  });

  test('DELETE /users returns 404 (method not registered)', async () => {
    const response = await request(app).delete('/users');
    expect(response.status).toBe(404);
  });

  test('PATCH /users returns 404 (method not registered)', async () => {
    const response = await request(app).patch('/users').send({});
    expect(response.status).toBe(404);
  });
});

// =============================================================================
// 4. EDGE-CASE / ADDITIONAL TESTS
// =============================================================================
describe('GET /users – edge cases and headers', () => {
  test('responds successfully with an Accept: application/json header', async () => {
    const response = await request(app)
      .get('/users')
      .set('Accept', 'application/json');
    expect(response.status).toBe(200);
    expect(Array.isArray(response.body)).toBe(true);
  });

  test('trailing slash /users/ also returns 404 (strict routing default)', async () => {
    const response = await request(app).get('/users/');
    // Express with default settings returns 404 for unregistered trailing-slash paths.
    expect(response.status).toBe(404);
  });

  test('handles query params gracefully and still returns 200', async () => {
    const response = await request(app).get('/users?page=1&limit=10');
    expect(response.status).toBe(200);
    expect(Array.isArray(response.body)).toBe(true);
  });

  test('response does not expose sensitive server headers', async () => {
    const response = await request(app).get('/users');
    expect(response.headers['x-powered-by']).toBe('Express'); // default; change assertion if header is removed for hardening
  });

  test('concurrent requests all succeed with identical data', async () => {
    const responses = await Promise.all(
      Array.from({ length: 5 }, () => request(app).get('/users'))
    );
    responses.forEach((res) => {
      expect(res.status).toBe(200);
      expect(res.body).toHaveLength(2);
    });
    // All responses should be identical
    const bodies = responses.map((r) => JSON.stringify(r.body));
    const unique = new Set(bodies);
    expect(unique.size).toBe(1);
  });

  test('response body is valid JSON (no raw-string parsing error)', async () => {
    const response = await request(app).get('/users');
    expect(() => JSON.stringify(response.body)).not.toThrow();
  });
});

