const express = require('express');
const app = express();

app.use(express.json());

// In-memory user store — swap for a real DB layer in production
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ── Routes ──────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Returns the full list of users.
 * Responds with 500 if the data layer throws.
 */
app.get('/users', (req, res) => {
  try {
    const data = app.locals.getUsersFn ? app.locals.getUsersFn() : users;
    res.status(200).json(data);
  } catch (err) {
    res.status(500).json({ error: 'Internal server error', message: err.message });
  }
});

/**
 * GET /users/:id
 * Returns a single user by numeric id.
 * 400 for a non-numeric id, 404 when the user is not found.
 */
app.get('/users/:id', (req, res) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id <= 0) {
    return res.status(400).json({ error: 'Bad request', message: 'id must be a positive integer' });
  }

  try {
    const store = app.locals.getUsersFn ? app.locals.getUsersFn() : users;
    const user  = store.find((u) => u.id === id);
    if (!user) {
      return res.status(404).json({ error: 'Not found', message: `User ${id} does not exist` });
    }
    res.status(200).json(user);
  } catch (err) {
    res.status(500).json({ error: 'Internal server error', message: err.message });
  }
});

// ── Server ───────────────────────────────────────────────────────────────────

/* istanbul ignore next */
if (require.main === module) {
  app.listen(3000, () => console.log('Server running on port 3000'));
}

module.exports = { app, users };

