/**
 * app.test.js
 *
 * Unit / integration tests for the Express application.
 * Focus: GET /users  (list) and GET /users/:id  (single user)
 *
 * Run:  npx jest --verbose
 * Deps: jest, supertest  (npm install --save-dev jest supertest)
 */

'use strict';

const request = require('supertest');
const { app, users } = require('./app');

// ─── Schema helper ───────────────────────────────────────────────────────────

/**
 * Validates that a value matches the expected User schema.
 *
 * Expected shape:
 *   { id: <positive integer>, name: <non-empty string>, email: <valid email> }
 *
 * Returns an array of violation strings (empty = valid).
 */
function validateUserSchema(user) {
  const violations = [];

  if (typeof user !== 'object' || user === null || Array.isArray(user)) {
    return ['user must be a plain object'];
  }

  // id
  if (!Object.prototype.hasOwnProperty.call(user, 'id')) {
    violations.push('missing field: id');
  } else if (!Number.isInteger(user.id) || user.id <= 0) {
    violations.push(`id must be a positive integer, got: ${JSON.stringify(user.id)}`);
  }

  // name
  if (!Object.prototype.hasOwnProperty.call(user, 'name')) {
    violations.push('missing field: name');
  } else if (typeof user.name !== 'string' || user.name.trim() === '') {
    violations.push(`name must be a non-empty string, got: ${JSON.stringify(user.name)}`);
  }

  // email — simple RFC-5321-inspired check
  const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!Object.prototype.hasOwnProperty.call(user, 'email')) {
    violations.push('missing field: email');
  } else if (typeof user.email !== 'string' || !EMAIL_RE.test(user.email)) {
    violations.push(`email must be a valid address, got: ${JSON.stringify(user.email)}`);
  }

  // No extra keys allowed
  const ALLOWED = new Set(['id', 'name', 'email']);
  Object.keys(user).forEach((k) => {
    if (!ALLOWED.has(k)) violations.push(`unexpected field: ${k}`);
  });

  return violations;
}

// ─── Seed data ────────────────────────────────────────────────────────────────

// Mirror of the in-memory store so tests can make assertions without
// coupling to the live array reference.
const SEED_USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ─── Test lifecycle ───────────────────────────────────────────────────────────

beforeEach(() => {
  // Reset any test-double injected via app.locals between tests
  delete app.locals.getUsersFn;
});

// ═════════════════════════════════════════════════════════════════════════════
// GET /users — happy path
// ═════════════════════════════════════════════════════════════════════════════

describe('GET /users — happy path', () => {
  test('responds with HTTP 200', async () => {
    const res = await request(app).get('/users');
    expect(res.statusCode).toBe(200);
  });

  test('Content-Type header is application/json', async () => {
    const res = await request(app).get('/users');
    expect(res.headers['content-type']).toMatch(/application\/json/);
  });

  test('response body is an array', async () => {
    const res = await request(app).get('/users');
    expect(Array.isArray(res.body)).toBe(true);
  });

  test('returns the correct number of users', async () => {
    const res = await request(app).get('/users');
    expect(res.body).toHaveLength(SEED_USERS.length);
  });

  test('returns the expected user data', async () => {
    const res = await request(app).get('/users');
    expect(res.body).toEqual(SEED_USERS);
  });

  test('list is not empty', async () => {
    const res = await request(app).get('/users');
    expect(res.body.length).toBeGreaterThan(0);
  });

  test('IDs in the list are unique', async () => {
    const res = await request(app).get('/users');
    const ids = res.body.map((u) => u.id);
    expect(new Set(ids).size).toBe(ids.length);
  });
});

// ═════════════════════════════════════════════════════════════════════════════
// GET /users — response schema validation
// ═════════════════════════════════════════════════════════════════════════════

describe('GET /users — response schema', () => {
  test('every user object contains exactly the fields: id, name, email', async () => {
    const res = await request(app).get('/users');
    res.body.forEach((user, i) => {
      const violations = validateUserSchema(user);
      expect(violations).toEqual(
        /* provide a readable failure message */
        expect.arrayContaining([]),
      );
      expect(violations).toHaveLength(0);
    });
  });

  test('id is a positive integer for every user', async () => {
    const res = await request(app).get('/users');
    res.body.forEach((user) => {
      expect(Number.isInteger(user.id)).toBe(true);
      expect(user.id).toBeGreaterThan(0);
    });
  });

  test('name is a non-empty string for every user', async () => {
    const res = await request(app).get('/users');
    res.body.forEach((user) => {
      expect(typeof user.name).toBe('string');
      expect(user.name.trim().length).toBeGreaterThan(0);
    });
  });

  test('email matches a valid email format for every user', async () => {
    const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const res = await request(app).get('/users');
    res.body.forEach((user) => {
      expect(typeof user.email).toBe('string');
      expect(EMAIL_RE.test(user.email)).toBe(true);
    });
  });

  test('schema validator helper correctly rejects malformed objects', () => {
    // Missing fields
    expect(validateUserSchema({})).not.toHaveLength(0);
    // Wrong id type
    expect(validateUserSchema({ id: 'x', name: 'X', email: 'x@x.com' })).not.toHaveLength(0);
    // Invalid email
    expect(validateUserSchema({ id: 1, name: 'X', email: 'not-an-email' })).not.toHaveLength(0);
    // Extra field
    expect(validateUserSchema({ id: 1, name: 'X', email: 'x@x.com', role: 'admin' })).not.toHaveLength(0);
    // Null
    expect(validateUserSchema(null)).not.toHaveLength(0);
    // Valid object produces zero violations
    expect(validateUserSchema({ id: 1, name: 'X', email: 'x@x.com' })).toHaveLength(0);
  });
});

// ═════════════════════════════════════════════════════════════════════════════
// GET /users/:id — happy path
// ═════════════════════════════════════════════════════════════════════════════

describe('GET /users/:id — happy path', () => {
  test('returns HTTP 200 for an existing user', async () => {
    const res = await request(app).get('/users/1');
    expect(res.statusCode).toBe(200);
  });

  test('returns the correct user object', async () => {
    const res = await request(app).get('/users/1');
    expect(res.body).toEqual(SEED_USERS[0]);
  });

  test('returns different users for different IDs', async () => {
    const [res1, res2] = await Promise.all([
      request(app).get('/users/1'),
      request(app).get('/users/2'),
    ]);
    expect(res1.body).toEqual(SEED_USERS[0]);
    expect(res2.body).toEqual(SEED_USERS[1]);
    expect(res1.body.id).not.toBe(res2.body.id);
  });

  test('single-user response matches the User schema', async () => {
    const res = await request(app).get('/users/1');
    expect(validateUserSchema(res.body)).toHaveLength(0);
  });
});

// ═════════════════════════════════════════════════════════════════════════════
// GET /users/:id — error handling
// ═════════════════════════════════════════════════════════════════════════════

describe('GET /users/:id — error handling', () => {
  test('returns HTTP 404 for a non-existent user id', async () => {
    const res = await request(app).get('/users/9999');
    expect(res.statusCode).toBe(404);
  });

  test('404 body contains an error field', async () => {
    const res = await request(app).get('/users/9999');
    expect(res.body).toHaveProperty('error');
  });

  test('404 body contains a human-readable message field', async () => {
    const res = await request(app).get('/users/9999');
    expect(res.body).toHaveProperty('message');
    expect(typeof res.body.message).toBe('string');
    expect(res.body.message.length).toBeGreaterThan(0);
  });

  test('returns HTTP 400 for a non-numeric id', async () => {
    const res = await request(app).get('/users/abc');
    expect(res.statusCode).toBe(400);
  });

  test('400 body contains an error field', async () => {
    const res = await request(app).get('/users/abc');
    expect(res.body).toHaveProperty('error');
  });

  test('returns HTTP 400 for a negative id', async () => {
    const res = await request(app).get('/users/-5');
    expect(res.statusCode).toBe(400);
  });

  test('returns HTTP 400 for id zero', async () => {
    const res = await request(app).get('/users/0');
    expect(res.statusCode).toBe(400);
  });
});

// ═════════════════════════════════════════════════════════════════════════════
// GET /users — error handling (data-layer failure)
// ═════════════════════════════════════════════════════════════════════════════

describe('GET /users — error handling', () => {
  test('returns HTTP 500 when the data layer throws', async () => {
    app.locals.getUsersFn = () => {
      throw new Error('Database connection lost');
    };
    const res = await request(app).get('/users');
    expect(res.statusCode).toBe(500);
  });

  test('500 body contains an error field', async () => {
    app.locals.getUsersFn = () => {
      throw new Error('Database connection lost');
    };
    const res = await request(app).get('/users');
    expect(res.body).toHaveProperty('error');
  });

  test('500 body contains a message field with the underlying error text', async () => {
    app.locals.getUsersFn = () => {
      throw new Error('Database connection lost');
    };
    const res = await request(app).get('/users');
    expect(res.body).toHaveProperty('message', 'Database connection lost');
  });

  test('does NOT leak a stack trace in the error response', async () => {
    app.locals.getUsersFn = () => {
      throw new Error('boom');
    };
    const res = await request(app).get('/users');
    const bodyStr = JSON.stringify(res.body);
    expect(bodyStr).not.toMatch(/at Object\./);   // no stack-frame lines
    expect(bodyStr).not.toMatch(/node_modules/);
  });

  test('returns HTTP 500 for GET /users/:id when data layer throws', async () => {
    app.locals.getUsersFn = () => {
      throw new Error('Timeout');
    };
    const res = await request(app).get('/users/1');
    expect(res.statusCode).toBe(500);
  });
});

// ═════════════════════════════════════════════════════════════════════════════
// Idempotency & side-effect checks
// ═════════════════════════════════════════════════════════════════════════════

describe('GET /users — idempotency', () => {
  test('two consecutive calls return identical payloads', async () => {
    const [res1, res2] = await Promise.all([
      request(app).get('/users'),
      request(app).get('/users'),
    ]);
    expect(res1.body).toEqual(res2.body);
  });

  test('GET /users is read-only — a second call still returns all users', async () => {
    await request(app).get('/users');
    const res = await request(app).get('/users');
    expect(res.body).toHaveLength(SEED_USERS.length);
  });
});

