/**
 * Validates that a value matches the expected User schema.
 *
 * Expected shape:
 *   { id: <positive integer>, name: <non-empty string>, email: <valid email> }
 *
 * Returns an array of violation strings (empty = valid).
 */
function validateUserSchema(user) {
  const violations = [];

  if (typeof user !== 'object' || user === null || Array.isArray(user)) {
    return ['user must be a plain object'];
  }

  // id
  if (!Object.prototype.hasOwnProperty.call(user, 'id')) {
    violations.push('missing field: id');
  } else if (!Number.isInteger(user.id) || user.id <= 0) {
    violations.push(`id must be a positive integer, got: ${JSON.stringify(user.id)}`);
  }

  // name
  if (!Object.prototype.hasOwnProperty.call(user, 'name')) {
    violations.push('missing field: name');
  } else if (typeof user.name !== 'string' || user.name.trim() === '') {
    violations.push(`name must be a non-empty string, got: ${JSON.stringify(user.name)}`);
  }

  // email — simple RFC-5321-inspired check
  const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!Object.prototype.hasOwnProperty.call(user, 'email')) {
    violations.push('missing field: email');
  } else if (typeof user.email !== 'string' || !EMAIL_RE.test(user.email)) {
    violations.push(`email must be a valid address, got: ${JSON.stringify(user.email)}`);
  }

  // No extra keys allowed
  const ALLOWED = new Set(['id', 'name', 'email']);
  Object.keys(user).forEach((k) => {
    if (!ALLOWED.has(k)) violations.push(`unexpected field: ${k}`);
  });

  return violations;
}

